// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 10 ether);

        Reverter bad = new Reverter();

        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: 10 ether}("");
        require(sent);

        vm.assume(address(c).balance >= amount);

        vm.deal(address(bad), 1 ether);

        bool ok;
        try c.withdraw{gas: gasleft()}(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;
        uint256 balBefore = 10 ether;

        if (ok) {
            assertTrue(balBefore - balAfter == amount);
        } else {
            assertTrue(true);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("bad");
    }
    receive() external payable {
        revert("bad");
    }
}
